from mk import matn, norm_map, nn
from sh import page
def ih(pid,start,end,book='23833'):
  t=page(book,pid)[2]; t=re.sub(r'\[[٠-٩0-9]+\]','',t); t=t.replace('⟦','').replace('⟧','')
  s,ix=norm_map(t); a=s.find(nn(start)); assert a>=0,(pid,start); b=s.find(nn(end),a); assert b>=0,(pid,end); b+=len(nn(end))
  m=t[ix[a]:ix[b-1]+1]; m=re.sub(r'صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ|صلى الله عليه وسلم','ﷺ',m)
  return re.sub(r'\s+',' ',m).strip(), 0
