ABR={'KN09','KN21','KN23','KN24','KN28','KN31','KN32','KN33','KN35','KN39','KN42','KN46','KN49'}
out=[];quiz=[]
for i,(title,text,src,grade,nar,m,q,a,w) in enumerate(C,1):
  cid=f'KN{i:02d}'
  if m[0]=='ih': mt,_=ih(m[1],m[2],m[3]); nar=nar or 'ابن إسحاق'
  elif m[0]=='fath': mt,_=ih(m[1],m[2],m[3],'1673')
  else: mt,_=matn(m[0],m[1],m[2],m[3],m[4] if len(m)>4 else None)
  mt=mt.strip()
  if mt.endswith('«'): mt='«'+mt[:-1].rstrip()+'»'
  mt=mt.replace(' «.','».').replace(' «،','»،')
  mt=mt.replace('فَقَالَ» نَعَمْ','فَقَالَ «نَعَمْ').replace('عَلَّمَ بِالْقَلَمِ','عَلَّمَ بِالْقَلَمِ}»') if cid in ('KN12','KN23') else mt
  if cid=='KN23' and not mt.endswith('»'): mt+='}»'
  if '»' in mt and (mt.find('«')<0 or mt.find('»')<mt.find('«')): mt='«'+mt
  card={'id':cid,'chapter':CH,'title':title,'text':text,'source':src,'grade':grade,'theme':'navy','long':len(text)>230,'hadith':{'matn':mt,'narrator':nar or '','excerpt':False}}
  if cid in ABR: card['hadith']['excerpt']=True; card['abridged']=True
  out.append(card); quiz.append({'card':cid,'q':q,'a':a,'w':w})
json.dump({'chapter':CH,'cards':out,'quiz':quiz},open('/home/user/habibuna-app/data/batch13/batch1.json','w'),ensure_ascii=False,indent=1)
